from taf.collectors.core.factories.collector_factory import RemoteCommandCollectorFactory
from taf.collectors.core.factories.factory import Factory
from taf.collectors.core.factories.named_factory import NamedComponentFactory
from taf.collectors.kubernetes.collector import PodCollector, SingleContainerCollector, MultiContainerCollector

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class KubernetesCollectorFactory(NamedComponentFactory):
    """
    Factory to create kubernetes collectors.
    """
    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(KubernetesCollectorFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        resulting_arguments["namespace"] = configuration["namespace"]
        resulting_arguments["pod_name"] = configuration["pod_name"]
        if "target_file_name" in configuration:
            resulting_arguments["target_file_name"] = configuration["target_file_name"]


class SingleContainerCollectorFactory(KubernetesCollectorFactory, RemoteCommandCollectorFactory):
    def create(self, configuration, existing_arguments):
        """
        Create a kubernetes container collector for single container.

        :param dict configuration:
                collection of configuration parameters for the object to be created and other objects,
                that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)

        :return: SingleContainerCollector
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments,
                              resulting_arguments=resulting_arguments)
        resulting_arguments["container"] = configuration["container"]
        return SingleContainerCollector(**resulting_arguments)


class MultiContainerCollectorFactory(KubernetesCollectorFactory, RemoteCommandCollectorFactory):
    def create(self, configuration, existing_arguments):
        """
        Create a kubernetes pod collector with one log per container of the pod.

        :param dict configuration:
                collection of configuration parameters for the object to be created and other objects,
                that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)

        :return: MultiContainerCollector
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments,
                              resulting_arguments=resulting_arguments)
        return MultiContainerCollector(**resulting_arguments)


class PodCollectorFactory(KubernetesCollectorFactory, RemoteCommandCollectorFactory):
    def create(self, configuration, existing_arguments):
        """
       Create a kubernetes pod collector with one log for all containers of the pod.

        :param dict configuration:
                collection of configuration parameters for the object to be created and other objects,
                that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)

        :return: PodCollector
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments,
                              resulting_arguments=resulting_arguments)
        return PodCollector(**resulting_arguments)


class KubernetesCollectorFactorySelector(Factory):
    def create(self, configuration, existing_arguments):
        if "container" in configuration:
            return SingleContainerCollectorFactory().create(configuration=configuration,
                                                            existing_arguments=existing_arguments)
        if "merge_container_logs" in configuration:
            if configuration["merge_container_logs"]:
                return PodCollectorFactory().create(configuration=configuration,
                                                    existing_arguments=existing_arguments)
            else:
                return MultiContainerCollectorFactory().create(configuration=configuration,
                                                               existing_arguments=existing_arguments)
